```ts
Deno.serve((req) => {
  // Ojo: cf-ipcountry lo agrega Cloudflare. Verifica si tu plataforma
  // lo entrega (otra puede usar un header distinto) y qué valor trae
  // cuando no puede determinar el país.
  const pais = req.headers.get("cf-ipcountry");
  const destino = pais === "CL" ? "/es-cl" : "/en";
  const url = new URL(destino, req.url);
  return Response.redirect(url.toString(), 302);
});
