const crypto = require("crypto");

const sha = (t) => crypto.createHash("sha256").update(t).digest("hex");

function crearBloque(previo, datos) {
  const hashPrevio = previo ? previo.hash : "0";
  return { datos, hashPrevio, hash: sha(hashPrevio + datos) };
}

function verificar(cadena) {
  for (let i = 0; i < cadena.length; i++) {
    const b = cadena[i];
    if (b.hash !== sha(b.hashPrevio + b.datos)) return false;
    if (i > 0 && b.hashPrevio !== cadena[i - 1].hash) return false;
  }
  return true;
}
